using System.Globalization;using System.Windows;using Crown___Sovereign.Models;using Crown___Sovereign.Services;namespace Crown___Sovereign.Views.Dialogs.Gerencia;public partial class TarifaDialog:Window{private readonly TarifaModel _rate;public TarifaDialog(TarifaModel rate){InitializeComponent();_rate=rate;RoomTypeText.Text=$"{rate.TipoHabitacion} · {rate.Temporada}";PriceBox.Text=rate.Precio.ToString(CultureInfo.CurrentCulture);}private void Save_Click(object s,RoutedEventArgs e){if(!decimal.TryParse(PriceBox.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var price)){MessageBox.Show(this,"Indica un precio válido.","Dato inválido",MessageBoxButton.OK,MessageBoxImage.Warning);return;}try{new GerenciaService().ActualizarTarifa(_rate.Id,price);DialogResult=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"No se pudo guardar",MessageBoxButton.OK,MessageBoxImage.Warning);}}private void Cancel_Click(object s,RoutedEventArgs e)=>Close();}
